/* U: «живая» панель NOX в колонке виджетов чата. Вкладки: Задачи (канбан агентов), Карточки (worms: находки и самоулучшение), Идеи дня, Чему научился.
   API: /svc/agentsb/{board,task/<id>/cancel,worms/*,lessons,consilium}. Анимации: vendor/auto-animate. API NOXboard */
(function(){ if(window.NOXboard)return;
 const B='/svc/agentsb',COLS=['В работе','Нужен ты','Готово'],CLS={'В работе':'running','Нужен ты':'blocked','Готово':'done'};
 let box,ctl=null,tab=localStorage.getItem('nox.ub.tab')||'tasks',D={board:{},cards:{hunt:[],self:[]},learned:[],lessons:[],agenda:{ideas:[]}};
 const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 const eta=s=>!s?'':(s>=3600?Math.round(s/3600)+' ч':s>=60?Math.round(s/60)+' мин':s+' с');
 const J=(p,o)=>fetch(B+p,Object.assign({cache:'no-store',headers:{'Content-Type':'application/json'}},o)).then(r=>r.ok?r.json():null).catch(()=>null);
 const P=(p,b)=>J(p,{method:'POST',body:JSON.stringify(b||{})});
 const empty=(t,h)=>'<div class="ub-e"><b>'+t+'</b><span>'+h+'</span><button type="button" class="ub-ask" data-ask="'+esc(h)+'">Спросить NOX</button></div>';
 function task(c){return '<div class="ub-c"><div class="ub-t">'+esc(c.title)+'</div><div class="ub-m">'+esc(c.stage||'')+(c.pct!=null?' · '+c.pct+'%':'')+(c.eta_sec?' · ETA '+eta(c.eta_sec):'')+'</div>'+(c.blocker?'<div class="ub-b">Стопор: '+esc(c.blocker)+'</div>':'')+'<div class="ub-bar"><i style="width:'+Math.max(0,Math.min(100,+c.pct||0))+'%"></i></div>'+(c.column==='Готово'?'':'<button type="button" class="ub-x" data-cancel="'+esc(c.id)+'">Отменить</button>')+'</div>'}
 function vTasks(){const n=COLS.reduce((a,k)=>a+((D.board[k]||[]).length),0);if(!n)return empty('Задач нет','Поручи NOX задачу: «собери команду и сделай…»');
  return COLS.map(k=>{const a=D.board[k]||[];return '<details'+(k!=='Готово'?' open':'')+'><summary class="k8-s '+CLS[k]+'">'+k+' · '+a.length+'</summary>'+a.slice(0,8).map(task).join('')+'</details>'}).join('')}
 function vCards(){const h=D.cards.hunt||[],s=D.cards.self||[];if(!h.length&&!s.length)return empty('Новых находок нет','Попроси NOX поискать модели и улучшения для себя');
  return h.map(c=>'<div class="ub-c"><div class="ub-t">'+esc(c.text)+'</div><div class="ub-m">лицензия '+esc(c.license||'?')+' · оценка '+esc(c.score)+'</div><div class="ub-r"><button type="button" class="ub-ok" data-ap="hunt:'+c.id+':1">Разрешаю</button><button type="button" data-ap="hunt:'+c.id+':0">Нет</button></div></div>').join('')+
  s.map(c=>'<div class="ub-c"><div class="ub-t">'+esc(c.text)+'</div><div class="ub-r"><button type="button" class="ub-ok" data-ap="self:'+c.id+':1">Разрешаю</button><button type="button" data-ap="self:'+c.id+':0">Нет</button><button type="button" data-rb="'+c.id+'">Откатить</button></div></div>').join('')}
 function vIdeas(){const a=(D.agenda&&D.agenda.ideas)||[];const dr=D.agenda&&D.agenda.dream?'<div class="ub-m">'+esc(D.agenda.dream)+'</div>':'';if(!a.length)return dr+empty('Идей на сегодня нет','Попроси NOX составить утреннюю повестку')+'<button type="button" data-mk="1">Составить повестку</button>';
  return dr+a.map(i=>'<div class="ub-c"><div class="ub-t">'+esc(i.title)+'</div><div class="ub-m">'+esc(i.why||'')+'</div>'+(i.status==='developing'?'<div class="ub-m">развивается…</div>':'<button type="button" class="ub-ok" data-dev="'+i.id+'">Развить</button>')+'</div>').join('')}
 function vLearn(){const a=[].concat(D.learned||[]).slice(0,12),l=[].concat(D.lessons||[]).slice(-8).reverse();if(!a.length&&!l.length)return empty('Пока ничего не выучено','Скажи NOX, чему научиться, и он запишет урок');
  return a.map(x=>'<div class="ub-c"><div class="ub-m">'+esc(String(x.ts||'').slice(0,16))+'</div><div>'+esc(x.text)+'</div></div>').join('')+(l.length?'<div class="ub-m">Уроки</div>':'')+l.map(x=>'<div class="ub-c"><div>'+esc(x.lesson||x.text||x.what||JSON.stringify(x).slice(0,160))+'</div>'+(x.rule?'<div class="ub-m">Правило: '+esc(x.rule)+'</div>':'')+'</div>').join('')}
 const V={tasks:vTasks,cards:vCards,ideas:vIdeas,learn:vLearn},N={tasks:'Задачи',cards:'Карточки',ideas:'Идеи',learn:'Выучено'};
 function render(){ if(!box)return;const b=box.querySelector('.ub-body');b.innerHTML=V[tab]();box.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-selected',x.dataset.tab===tab));
  const n={tasks:(D.board['Нужен ты']||[]).length,cards:(D.cards.hunt||[]).length+(D.cards.self||[]).length,ideas:((D.agenda&&D.agenda.ideas)||[]).filter(i=>i.status!=='developing').length,learn:0};box.querySelectorAll('[data-tab]').forEach(x=>{x.querySelector('i').textContent=n[x.dataset.tab]||''})}
 async function load(){ if(document.hidden)return;const [b,c,l,ls,ag]=await Promise.all([J('/board'),J('/worms/cards'),J('/worms/learned'),J('/lessons'),J('/worms/agenda')]);if(b)D.board=b;if(c)D.cards=c;if(l)D.learned=l;if(ls)D.lessons=ls;if(ag)D.agenda=ag;render()}
 function say(t){const i=document.getElementById('input');if(i){i.value=t;i.dispatchEvent(new Event('input',{bubbles:true}));i.focus()}}
 function flash(m){const t=box.querySelector('.ub-st');t.textContent=m;setTimeout(()=>{t.textContent=''},3000)}
 async function click(e){const t=e.target.closest('button');if(!t)return;
  if(t.dataset.tab){tab=t.dataset.tab;localStorage.setItem('nox.ub.tab',tab);return render()}
  if(t.dataset.cancel){await P('/task/'+t.dataset.cancel+'/cancel');flash('Задача отменена');return load()}
  if(t.dataset.ap){const [k,id,y]=t.dataset.ap.split(':');const r=await P(k==='self'?'/worms/self/approve':'/worms/approve',{id:+id,yes:y==='1'});flash(r&&r.ok?(y==='1'?'Принято':'Отклонено'):((r&&r.error)||'Не вышло'));if(y==='1'&&r&&r.ok&&window.K8win)K8win.fire('Принято');return load()}
  if(t.dataset.rb){const r=await P('/worms/self/rollback/'+t.dataset.rb);flash(r&&r.ok?'Откат выполнен':'Откат невозможен');return load()}
  if(t.dataset.dev){const r=await P('/worms/develop',{id:+t.dataset.dev});flash(r&&r.ok?'Идея в работе':'Не вышло');return load()}
  if(t.dataset.mk){await P('/worms/agenda/make');flash('Повестка составлена');return load()}
  if(t.dataset.ask)return say(t.dataset.ask);
  if(t.id==='ub-deep'){const i=document.getElementById('input'),q=i&&i.value.trim();if(!q)return flash('Напиши вопрос в поле чата');t.disabled=true;flash('Думаю глубже…');const r=await P('/consilium',{question:q,deep:true});t.disabled=false;const a=r&&(r.answer||r.final||r.text||r.result);flash(a?'Готово':'Консилиум не ответил');if(a&&i){i.value=String(typeof a==='string'?a:JSON.stringify(a)).slice(0,3000);i.dispatchEvent(new Event('input',{bubbles:true}))}}}
 let tries=0;function mount(){ if(box||!document.body)return;const host=document.querySelector('.cx-right')||document.getElementById('tgWid');if(!host&&/chat/.test(location.pathname)&&++tries<30)return setTimeout(mount,500);
  box=document.createElement('section');box.id='nox-u-board';box.setAttribute('aria-label','Панель NOX');
  box.innerHTML='<style>@media(max-width:768px){#nox-u-board.fl{display:none}}#nox-u-board{font-size:14px;color:inherit;max-width:100%;box-sizing:border-box;margin:8px 0;padding:8px;border-radius:16px;background:linear-gradient(160deg,rgba(255,255,255,.10),rgba(255,255,255,.03));backdrop-filter:blur(18px) saturate(1.4);-webkit-backdrop-filter:blur(18px) saturate(1.4);border:1px solid rgba(255,255,255,.14);box-shadow:0 8px 32px rgba(0,0,0,.25),0 0 28px var(--k8-glow,transparent)}#nox-u-board.fl{position:fixed;left:12px;bottom:120px;width:320px;max-height:60vh;overflow:auto;z-index:40}#nox-u-board .ub-tabs{display:flex;gap:4px;flex-wrap:wrap}#nox-u-board .ub-tabs button{flex:1;min-height:44px;border-radius:12px;border:1px solid transparent;background:transparent;color:inherit;font-size:14px;cursor:pointer;transition:background .2s}#nox-u-board .ub-tabs button[aria-selected=true]{background:rgba(233,180,101,.2);border-color:rgba(233,180,101,.5)}#nox-u-board .ub-tabs i{font-style:normal;margin-left:4px;opacity:.8}#nox-u-board summary{min-height:44px;display:flex;align-items:center;cursor:pointer}#nox-u-board .ub-c{padding:8px 10px;margin:6px 0;border-radius:12px;background:rgba(255,255,255,.07);transition:transform .2s}#nox-u-board .ub-c:hover{transform:translateY(-1px)}#nox-u-board .ub-t{font-weight:600}#nox-u-board .ub-m,#nox-u-board .ub-b{font-size:14px;opacity:.85}#nox-u-board .ub-b{color:#ff9b9b}#nox-u-board .ub-bar{height:4px;border-radius:2px;background:rgba(255,255,255,.12);margin-top:4px}#nox-u-board .ub-bar i{display:block;height:100%;border-radius:2px;background:var(--k8-running,#e9b465);transition:width .6s}#nox-u-board .ub-r{display:flex;gap:6px;flex-wrap:wrap;margin-top:6px}#nox-u-board button:not([data-tab]){min-height:44px;min-width:44px;padding:0 12px;border-radius:12px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.08);color:inherit;font-size:14px;cursor:pointer}#nox-u-board .ub-ok{background:rgba(111,212,155,.22);border-color:rgba(111,212,155,.6)}#nox-u-board .ub-e{display:flex;flex-direction:column;gap:6px;padding:14px;border-radius:14px;border:1px dashed rgba(255,255,255,.25);text-align:center;align-items:center;animation:ubp 3s ease-in-out infinite}@keyframes ubp{50%{box-shadow:0 0 18px var(--k8-glow,rgba(233,180,101,.25))}}#nox-u-board .ub-e span{opacity:.8}#nox-u-board .ub-st{min-height:20px;font-size:14px;opacity:.9}</style><div class="ub-tabs" role="tablist">'+Object.keys(N).map(k=>'<button type="button" role="tab" data-tab="'+k+'">'+N[k]+'<i></i></button>').join('')+'</div><div class="ub-body"></div><div class="ub-r"><button type="button" id="ub-deep">Подумай глубже</button></div><div class="ub-st" role="status"></div>';
  if(host){host.appendChild(box)}else{box.classList.add('fl');document.body.appendChild(box)}
  box.addEventListener('click',click);
  import('./vendor/auto-animate/index.mjs').then(function(m){try{(m.default||m.autoAnimate)(box.querySelector('.ub-body'))}catch(e){}}).catch(function(){});
  load();setInterval(load,15000);document.addEventListener('visibilitychange',load)}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount);else mount();
 window.NOXboard={load:load,render:render,data:function(){return D}};
})();
